// Expected observations are generated by scripts/headless-reentry-oracle.mjs
// from unchanged source using the same queued-write + flushSync boundary.
use std::{cell::RefCell, rc::Rc};
use xterm_core::{
    headless::{QueuedTerminal, Terminal},
    input::write_buffer::WriteData,
};
fn line(term: &Terminal) -> String {
    let row = term
        .buffer()
        .unwrap()
        .active()
        .unwrap()
        .get_line(0)
        .unwrap()
        .unwrap();
    let text = row.borrow().translate_to_string(true, None, None, None);
    String::from_utf16(&text).unwrap()
}
#[test]
fn pa04_six_source_reentrant_paths_preserve_event_time_and_final_state() {
    for action in ["observe", "reset", "dispose", "resize", "input", "write"] {
        let terminal = Rc::new(Terminal::new(8, 3, 1000).unwrap());
        let host = QueuedTerminal::new(Rc::clone(&terminal)).unwrap();
        let events = Rc::new(RefCell::new(Vec::<String>::new()));
        let output = Rc::clone(&events);
        terminal.on_data().subscribe(move |data| {
            output
                .borrow_mut()
                .push(format!("data:{}", String::from_utf16(data).unwrap()))
        });
        let output = Rc::clone(&events);
        terminal.on_resize().subscribe(move |size| {
            output
                .borrow_mut()
                .push(format!("resize:{}:{}", size.cols, size.rows))
        });
        let output = Rc::clone(&events);
        let target = Rc::downgrade(&terminal);
        let queue = host.queue();
        terminal.on_bell().subscribe(move |_| {
            let terminal = target.upgrade().unwrap();
            output
                .borrow_mut()
                .push(format!("bell:{}", line(&terminal)));
            match action {
                "reset" => terminal.reset().unwrap(),
                "dispose" => terminal.dispose().unwrap(),
                "resize" => terminal.resize(6, 3).unwrap(),
                "input" => terminal
                    .input(&"in".encode_utf16().collect::<Vec<_>>(), true)
                    .unwrap(),
                "write" => {
                    let output = Rc::clone(&output);
                    queue
                        .write(
                            WriteData::text("C"),
                            Some(Rc::new(move |_| {
                                output.borrow_mut().push("inner-callback".into());
                                Ok(())
                            })),
                        )
                        .unwrap();
                }
                "observe" => {}
                _ => unreachable!(),
            }
        });
        let output = Rc::clone(&events);
        host.write(
            WriteData::text("A\x07B"),
            Some(Rc::new(move |_| {
                output.borrow_mut().push("outer-callback".into());
                Ok(())
            })),
        )
        .unwrap();
        host.queue().flush_sync().unwrap();
        let expected = match action {
            "dispose" => vec!["bell:A"],
            "resize" => vec!["bell:A", "resize:6:3", "outer-callback"],
            "input" => vec!["bell:A", "data:in", "outer-callback"],
            "write" => vec!["bell:A", "outer-callback", "inner-callback"],
            _ => vec!["bell:A", "outer-callback"],
        };
        assert_eq!(*events.borrow(), expected, "{action}");
        assert_eq!(
            line(&terminal),
            match action {
                "reset" => "B",
                "write" => "ABC",
                _ => "AB",
            },
            "{action}"
        );
        assert_eq!(
            terminal.cols().unwrap(),
            if action == "resize" { 6 } else { 8 },
            "{action}"
        );
        assert_eq!(
            terminal.is_disposed().unwrap(),
            action == "dispose",
            "{action}"
        );
    }
}
